export const LANGUAGES=['de','en','ru'];
let language='de';
try{const saved=globalThis.localStorage?.getItem('my-menu:language');if(LANGUAGES.includes(saved))language=saved;}catch{}
export const getLocale=()=>language;
export function translate(text,locale='de'){
 if(typeof text!=='string'||locale==='ru')return text;
 const trimmed=text.trim(),entry=messages[trimmed];
 return entry?text.replace(trimmed,entry[locale]||trimmed):text;
}
export const t=text=>translate(text,language);
export function applyLanguage(locale){
 if(!LANGUAGES.includes(locale))return;
 try{localStorage.setItem('my-menu:language',locale);}catch{}
 location.reload();
}
export function initLanguage(){
 document.documentElement.lang=language;document.title=t(document.title);
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),nodes=[];let node;
 while(node=walker.nextNode())if(!['SCRIPT','STYLE','TEXTAREA'].includes(node.parentElement?.tagName))nodes.push(node);
 for(const node of nodes){const value=t(node.nodeValue);if(value!==node.nodeValue)node.nodeValue=value;}
 for(const element of document.querySelectorAll('[aria-label],[placeholder],[title],[alt]'))for(const attr of ['aria-label','placeholder','title','alt']){const value=element.getAttribute(attr);if(value)element.setAttribute(attr,t(value));}
 if(document.querySelector('[data-language-picker]'))return;
 const target=document.querySelector('.app-header,.users-page .section-head,.account-card');if(!target)return;
 const label=document.createElement('label');label.className='language-picker';label.dataset.languagePicker='';
 const select=document.createElement('select');select.setAttribute('aria-label',language==='de'?'Sprache':language==='en'?'Language':'Язык');
 for(const [value,text]of [['de','Deutsch'],['en','English'],['ru','Русский']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=language;
 select.addEventListener('change',()=>{const value=select.value;select.value=language;const request=new CustomEvent('cms-language-request',{detail:value,cancelable:true});if(document.dispatchEvent(request))applyLanguage(value);});label.append(select);target.append(label);
}
